"""Resolve a logical training record to its current backing file."""

import json
from pathlib import Path


def resolve(root, record):
    root = Path(root)
    digest = record["sha256"]
    catalog = root.joinpath("catalog.json")
    if catalog.is_file():
        rows = json.loads(catalog.read_text()).get("rows")
        for row in rows:
            if row.get("sha256") == digest:
                path = row.get("path")
                if path and root.joinpath(path).is_file():
                    return str(Path(path))
    pinned = record.get("path")
    if pinned and root.joinpath(pinned).is_file():
        return str(Path(pinned))
    raise FileNotFoundError(digest)
